css:
@page {
	size: 50mm 25mm;
	margin: 0;
}

.print-format {
	page-width: 50mm;
	page-height: 25mm;
	margin-top: 0mm;
	margin-bottom: 0mm;
	margin-left: 0mm;
	margin-right: 0mm;
	padding: 0;
	width: 50mm;
	max-width: 50mm;
	min-height: 0;
}

.print-format .afm-albl {
	box-sizing: border-box;
	width: 50mm;
	height: 25mm;
	padding: 2mm;
	overflow: hidden;
	direction: ltr;
	color: #171717;
	background-color: #FFFFFF;
	page-break-after: always;
	break-after: page;
}

.print-format .afm-albl-top {
	height: 6.2mm;
	overflow: hidden;
}

.print-format .afm-albl-logo {
	float: left;
	width: auto;
	max-width: 14mm;
	height: 5.4mm;
}

.print-format .afm-albl-name {
	max-height: 6.2mm;
	padding-left: 1mm;
	overflow: hidden;
	white-space: normal;
	word-wrap: break-word;
	text-align: right;
	font-size: 6.5pt;
	line-height: 3.1mm;
	font-weight: bold;
}

.print-format .afm-albl-bars {
	display: block;
	width: 46mm;
	height: 10.6mm;
	margin-top: 0.6mm;
}

.print-format .afm-albl-code {
	height: 3.6mm;
	line-height: 3.6mm;
	text-align: center;
	white-space: nowrap;
	overflow: hidden;
	direction: ltr;
	font-family: "Courier New", Courier, monospace;
	font-size: 8pt;
	font-weight: bold;
	letter-spacing: 0.2mm;
}
